/**
 * Generates src/data/erpData.ts with realistic coherent mock data.
 * Run: node scripts/generateErpData.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const outPath = path.join(__dirname, '..', 'src', 'data', 'erpData.ts')

const typesBlock = `// Keiros ERP - mock data for development screens
// Generated by scripts/generateErpData.mjs - re-run to refresh.
// Types / entity map: see ./schema.ts and ./entityMap.ts

export * from './schema'
import type {
  Complex,
  SiteProperty,
  Organization,
  User,
  Role,
  Building,
  Floor,
  MapLocation,
  MappingQueueItem,
  QualityIssue,
  Approval,
  Correction,
  MapVersion,
  Route,
  PropertyCode,
  CodeUsage,
  MapDownload,
  MobileSession,
  Journey,
  DwellMetric,
  Tour,
  TenantActivity,
  ApiClient,
  ApiKey,
  ApiUsageStat,
  ApiLog,
  Alert,
  AuditLog,
  SystemHealthService,
} from './schema'
`

function j(v) {
  return JSON.stringify(v)
}

function locId(n) {
  return `loc-${String(n).padStart(3, '0')}`
}

/** @type {Array<{id:string,buildingId:string,buildingName:string,complexId:string|null,complexName:string|null,label:string,level:number,mappedPct:number,address:string,lat:number,lng:number,elev:number,prefix:string,rooms:Array<{name:string,type:string,code:string,mapped?:boolean}>}>} */
const floorSpecs = []

function addFloor(spec) {
  floorSpecs.push(spec)
}

function gridRooms(items, cols = 4) {
  return items.map((item, i) => ({
    ...item,
    ox: ((i % cols) - (cols - 1) / 2) * 0.00011,
    oy: (Math.floor(i / cols) - 1) * 0.00009,
  }))
}

