// Build locations
const locations = []
let locN = 1
for (const floor of floorSpecs) {
  const propertyId = floor.complexId ?? floor.buildingId
  for (const room of floor.rooms) {
    const mapped = room.mapped !== false
    const lat = +(floor.lat + (room.ox || 0)).toFixed(6)
    const lng = +(floor.lng + (room.oy || 0)).toFixed(6)
    const namePart = room.name.includes(',') ? room.name : room.name
    locations.push({
      id: locId(locN++),
      floorId: floor.id,
      floorLabel: floor.label,
      buildingId: floor.buildingId,
      buildingName: floor.buildingName,
      complexId: floor.complexId,
      complexName: floor.complexName,
      propertyId,
      name: namePart,
      type: room.type,
      code: `${floor.prefix}-${room.code}`,
      mapped,
      physicalAddress: `${floor.address} Â· ${room.name}`,
      latitude: lat,
      longitude: lng,
      elevation: floor.elev,
    })
  }
}

const floors = floorSpecs.map((f) => {
  const locs = locations.filter((l) => l.floorId === f.id)
  const mapped = locs.filter((l) => l.mapped).length
  return {
    id: f.id,
    buildingId: f.buildingId,
    buildingName: f.buildingName,
    complexId: f.complexId,
    complexName: f.complexName,
    propertyId: f.complexId ?? f.buildingId,
    label: f.label,
    level: f.level,
    locations: locs.length,
    mappedPct: locs.length ? Math.round((mapped / locs.length) * 100) : f.mappedPct,
  }
})

