const siteProperties = [
  ...complexes.map((c) => ({
    id: c.id,
    kind: 'complex',
    name: c.name,
    city: c.city,
    organizationId: c.organizationId,
    organizationName: c.organizationName,
    status: c.status,
    complexId: c.id,
    buildingId: null,
    readiness: c.readiness,
    address: c.address,
  })),
  ...independentBuildings.map((b) => ({
    id: b.id,
    kind: 'independent',
    name: b.name,
    city: b.city,
    organizationId: b.organizationId,
    organizationName: b.organizationId === 'org-009' ? 'Bay Area Clinics LLC' : 'Embarcadero Holdings',
    status: b.status,
    complexId: null,
    buildingId: b.id,
    readiness: b.id === 'bld-ind-001' ? 91 : 64,
    address: b.id === 'bld-ind-001' ? clinicAddr : riverAddr,
  })),
]

const propertyByName = Object.fromEntries(siteProperties.map((p) => [p.name, p]))
const propertyLabels = siteProperties.map((p) => p.name)

function locsForProperty(propertyNameOrId) {
  const prop = propertyByName[propertyNameOrId] || siteProperties.find((p) => p.id === propertyNameOrId)
  if (!prop) return []
  return locations.filter((l) => l.propertyId === prop.id)
}

function floorsForProperty(propertyNameOrId) {
  const prop = propertyByName[propertyNameOrId] || siteProperties.find((p) => p.id === propertyNameOrId)
  if (!prop) return []
  return floors.filter((f) => f.propertyId === prop.id)
}

function findLoc(propertyName, name) {
  const pool = locsForProperty(propertyName)
  return (
    pool.find((l) => l.name === name) ||
    pool.find((l) => l.name.toLowerCase().includes(String(name).toLowerCase())) ||
    null
  )
}

function propertyFloorCount(propertyName) {
  const prop = propertyByName[propertyName]
  if (!prop) return floorsForProperty(propertyName).length
  if (prop.kind === 'complex') {
    const cpx = complexes.find((c) => c.id === prop.id)
    return cpx?.floors ?? floorsForProperty(propertyName).length
  }
  return independentBuildings.find((b) => b.id === prop.id)?.floors ?? floorsForProperty(propertyName).length
}

function pad(n, w = 3) {
  return String(n).padStart(w, '0')
}

function userByName(name) {
  return users.find((u) => u.name === name) || null
}

function floorByPropertyLabel(propertyName, preferred) {
  const fls = floorsForProperty(propertyName)
  if (!fls.length) return null
  return fls.find((f) => f.label === preferred) || fls[0]
}

