function haversineM(a, b) {
  const R = 6371000
  const toRad = (d) => (d * Math.PI) / 180
  const dLat = toRad(b.latitude - a.latitude)
  const dLng = toRad(b.longitude - a.longitude)
  const lat1 = toRad(a.latitude)
  const lat2 = toRad(b.latitude)
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLng / 2) ** 2
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)))
}

const routeNameOverrides = {
  'rt-001': 'Lobby to Suite 2201',
  'rt-002': 'Parking to Food Court',
  'rt-003': 'ER to Radiology',
  'rt-004': 'Entry to Unit 412',
  'rt-005': 'Visitor to Council Chamber',
  'rt-006': 'South Entry to Suite 1601',
  'rt-007': 'Valet to Residence 1408',
  'rt-008': 'Lobby to Fitness Center',
  'rt-009': 'Wing B Entry to Exam 312',
  'rt-010': 'Street Entry to Suite 801',
  'rt-011': 'West Entry to Cinema Lobby',
  'rt-012': 'Reception to Lab',
}

const routes = routeDefs.map((def) => {
  const prop = propertyByName[def.propertyName]
  const from = findLoc(def.propertyName, def.from)
  const to = findLoc(def.propertyName, def.to)
  if (!from || !to) throw new Error(`Route ${def.id}: missing endpoint on ${def.propertyName}`)
  const pool = locsForProperty(def.propertyName)
  const elevators = pool.filter((l) => l.type === 'Elevator')
  const mid =
    elevators.find((e) => e.buildingId === from.buildingId || e.buildingId === to.buildingId) ||
    pool.find((l) => l.type === 'Lobby' || l.type === 'Corridor') ||
    from
  const stops = from.floorId === to.floorId ? [from, to] : [from, mid, to]
  const dist = stops.slice(1).reduce((s, stop, i) => s + haversineM(stops[i], stop), 0)
  const floorChanges = new Set(stops.map((s) => s.floorId)).size - 1
  const durationMin =
    def.status === 'Draft'
      ? 0
      : Math.round(((dist / 1.2) / 60 + Math.max(0, floorChanges) * 0.6) * 10) / 10
  return {
    id: def.id,
    propertyId: prop.id,
    propertyName: prop.name,
    name: routeNameOverrides[def.id],
    waypoints: stops.length + Math.max(0, floorChanges) * 2 + 2,
    status: def.status,
    avgDurationMin: durationMin || (def.status === 'Draft' ? 0 : 3.5),
    fromLocationId: from.id,
    toLocationId: to.id,
  }
})

