/* â”€â”€â”€ FK validation â”€â”€â”€ */
const errors = []
const propIds = new Set(siteProperties.map((p) => p.id))
const locIds = new Set(locations.map((l) => l.id))
const floorIds = new Set(floors.map((f) => f.id))
const userIds = new Set(users.map((u) => u.id))
const mvIds = new Set(mapVersions.map((v) => v.id))
const routeIds = new Set(routes.map((r) => r.id))
const pcIds = new Set(propertyCodes.map((c) => c.id))
const clientIds = new Set(apiClients.map((c) => c.id))

for (const l of locations) if (!propIds.has(l.propertyId)) errors.push(`Location ${l.id} bad propertyId`)
for (const f of floors) if (!propIds.has(f.propertyId)) errors.push(`Floor ${f.id} bad propertyId`)
for (const r of routes) {
  if (!propIds.has(r.propertyId)) errors.push(`Route ${r.id} bad propertyId`)
  if (!locIds.has(r.fromLocationId) || !locIds.has(r.toLocationId)) errors.push(`Route ${r.id} bad location FK`)
}
for (const j of journeys) {
  if (!routeIds.has(j.routeId)) errors.push(`Journey ${j.id} bad routeId`)
  if (j.propertyId !== routes.find((r) => r.id === j.routeId)?.propertyId) errors.push(`Journey ${j.id} property/route mismatch`)
}
for (const u of codeUsage) {
  if (!pcIds.has(u.propertyCodeId)) errors.push(`Usage ${u.id} bad propertyCodeId`)
}
for (const d of mapDownloads) {
  if (!mvIds.has(d.mapVersionId)) errors.push(`Download ${d.id} bad mapVersionId`)
}
for (const a of approvals) {
  if (!mvIds.has(a.mapVersionId)) errors.push(`Approval ${a.id} bad mapVersionId`)
  if (!userIds.has(a.submittedByUserId)) errors.push(`Approval ${a.id} bad user`)
}
for (const c of corrections) {
  if (!locIds.has(c.locationId)) errors.push(`Correction ${c.id} bad locationId`)
}
for (const q of mappingQueue) {
  if (!floorIds.has(q.floorId)) errors.push(`Queue ${q.id} bad floorId`)
}
for (const d of dwellMetrics) {
  if (!locIds.has(d.locationId)) errors.push(`Dwell ${d.id} bad locationId`)
}
for (const t of tenantActivity) {
  if (!locIds.has(t.topDestinationLocationId)) errors.push(`Tenant ${t.id} bad locationId`)
}
for (const u of users) {
  if (!organizations.some((o) => o.id === u.organizationId)) errors.push(`User ${u.id} bad org`)
  if (!roles.some((r) => r.id === u.roleId)) errors.push(`User ${u.id} bad role`)
}
for (const k of apiKeys) {
  if (!clientIds.has(k.apiClientId)) errors.push(`Key ${k.id} bad client`)
}
if (errors.length) {
  console.error('Correlation errors:\n' + errors.join('\n'))
  process.exit(1)
}

